import { extension, type Resource, type Scope } from "@tinker/core";
import type { Migrations } from "../drizzle/migrations.ts";

/** Postgres advisory lock key shared by every migrate step on the same database.
 * Reserved for these migrations; other app locks and pg-boss must use another key. */
const migrationLock = { classId: 1937006964, objectId: 1 };

export declare namespace Migrate {
  export type Options = {
    migrationsFolder: string;
    /** Bring old app tables level and record their baseline, using this transaction only. */
    baseline?: (db: Migrations.Database) => Promise<void>;
  };
}

/** List right after server: settings are checked first, then migrations finish
 * before the port opens. The transaction pins one connection and releases its
 * advisory lock on commit or rollback. PGlite serializes these transactions too.
 * A later owner such as pg-boss can start after this commit, under its own lock. */
export function migrate(
  database: Resource.Handle<Promise<Migrations.Database>>,
  options: Migrate.Options,
): Scope.Extension<void> {
  return extension({
    label: "stack.migrate",
    hooks: {
      start: async (event) => {
        const { sql } = await import("drizzle-orm");
        const { migrateDatabase } = await import("../drizzle/migrations.ts");
        const db = await event.scope.resolve(database);
        await db.transaction(async (tx) => {
          await tx.execute(
            sql`select pg_advisory_xact_lock(${migrationLock.classId}, ${migrationLock.objectId})`,
          );
          await options.baseline?.(tx);
          await migrateDatabase(tx, { migrationsFolder: options.migrationsFolder });
        });
        await event.next();
      },
    },
  });
}

import type { Observe } from "@tinker/core";

export function describeError(error: unknown): Record<string, unknown> {
  if (!(error instanceof Error)) return { error: String(error) };
  const fields: Record<string, unknown> = { error: error.message, name: error.name };
  if ("kind" in error) fields.kind = error.kind;
  if ("payload" in error) fields.payload = error.payload;
  if (error.stack !== undefined) fields.stack = error.stack;
  if (error.cause !== undefined) fields.cause = describeError(error.cause);
  return fields;
}

/** One JSON object per line for a `write` (stdout at the entry): every log line
 * as `{ kind: "log", ... }`, and every failed span as `{ kind: "span", ... }` — an
 * ok span is a trace, and a trace is what a tracing backend is for. This is the
 * one place a logging or tracing backend swaps in: hand the root another
 * `Observe.Config` and nothing else in the app changes. A `write` that throws
 * loses that one line; core isolates the sink. */
export function jsonLines(write: (line: string) => void): Observe.Config {
  return {
    log: (entry) => {
      write(
        JSON.stringify({
          kind: "log",
          time: entry.time,
          level: entry.level,
          message: entry.message,
          span: entry.span?.id,
          ...entry.attributes,
        }),
      );
    },
    export: (span) => {
      if (span.status !== "failed") return;
      write(
        JSON.stringify({
          kind: "span",
          id: span.id,
          parent: span.parentId,
          name: span.name,
          unit: span.kind,
          start: span.start,
          end: span.end,
          status: span.status,
          ...span.attributes,
          events: span.events,
        }),
      );
    },
  };
}

import type { Observe } from "@tinker/core";

/** OTLP JSON uses decimal strings for uint64 times and hex for trace ids.
 * Core clocks supply epoch milliseconds; do the unit change in integer space. */
function nanos(time: number): string {
  return (BigInt(Math.trunc(time)) * 1_000_000n).toString();
}

function value(value: unknown): object {
  if (typeof value === "boolean") return { boolValue: value };
  if (typeof value === "bigint" || Number.isSafeInteger(value)) return { intValue: String(value) };
  if (typeof value === "number" && Number.isFinite(value)) return { doubleValue: value };
  if (typeof value === "string") return { stringValue: value };
  return { stringValue: JSON.stringify(value) ?? String(value) };
}

function attributes(fields: Record<string, unknown>): object[] {
  return Object.entries(fields).map(([key, entry]) => ({ key, value: value(entry) }));
}

/** Encode at flush, after the queue has retained the finished core span.
 * This is where lazy W3C ids are read and attributes become wire values. */
export function encodeSpan(span: Observe.Span): string {
  return JSON.stringify({
    traceId: span.traceId,
    spanId: span.spanId,
    parentSpanId: span.parentSpanId,
    flags: span.sampled ? 1 : 0,
    name: span.name,
    kind: 1,
    startTimeUnixNano: nanos(span.start),
    endTimeUnixNano: nanos(span.end!),
    attributes: attributes({ ...span.attributes, "tinker.kind": span.kind }),
    events: span.events.map((event) => ({
      name: event.name,
      timeUnixNano: nanos(event.time),
      attributes: attributes(event.attributes),
    })),
    status:
      span.status === "failed"
        ? {
            code: 2,
            message: span.error instanceof Error ? span.error.message : String(span.error),
          }
        : undefined,
  });
}

export function encodeLog(entry: Observe.Log): string {
  return JSON.stringify({
    timeUnixNano: nanos(entry.time),
    severityNumber: entry.level >= 50 ? 17 : entry.level >= 40 ? 13 : entry.level >= 30 ? 9 : 5,
    body: { stringValue: entry.message },
    attributes: attributes(entry.attributes),
    traceId: entry.span?.traceId,
    spanId: entry.span?.spanId,
    flags: entry.span?.sampled ? 1 : 0,
  });
}

export function encodeBatch(service: string, signal: "traces" | "logs", records: string[]): string {
  const resource = JSON.stringify({
    attributes: [{ key: "service.name", value: { stringValue: service } }],
  });
  const scope = JSON.stringify({ name: "tinker-source/stack" });
  return signal === "traces"
    ? `{"resourceSpans":[{"resource":${resource},"scopeSpans":[{"scope":${scope},"spans":[${records.join(",")}]}]}]}`
    : `{"resourceLogs":[{"resource":${resource},"scopeLogs":[{"scope":${scope},"logRecords":[${records.join(",")}]}]}]}`;
}

import { createElement, type ComponentType, type ReactNode } from "react";
import { ScopeProvider } from "@tinker/react";
import { extension, operation, type Operation, type Scope } from "@tinker/core";
import { emit, request, stream, type HonoScope } from "../hono/index.ts";

export declare namespace Pages {
  type Options<T> = {
    component: ComponentType;
    read: Operation.Handle<T, void>;
    render(request: Request, values: Awaited<T>, content: ReactNode): Promise<Response>;
  };
}

/** The renderer transfers its body to the request. A cancelled request cancels the
 * renderer's reader too, including a pending read; Hono owns commit and rollback. */
const pageBody = operation({
  label: "stack.pageBody",
  depends: { emit: emit.required },
  async run({ emit }, { input, signal }: Operation.Ctx<ReadableStream<Uint8Array>>) {
    const reader = input.getReader();
    let cancelled: Promise<void> | undefined;
    const cancel = () => {
      cancelled = reader.cancel();
    };
    signal.addEventListener("abort", cancel);
    try {
      if (signal.aborted) cancel();
      for (;;) {
        const chunk = await reader.read();
        if (chunk.done) break;
        emit(chunk.value);
      }
    } finally {
      signal.removeEventListener("abort", cancel);
      await cancelled;
      reader.releaseLock();
    }
  },
});

/** List the extension beside Hono and use mount in its wiring. Each request borrows
 * its session for React's provider; no scope crosses into the app's renderer.
 * Mount after API routes. Built assets fall through to the server's file routes. */
export function pages<T>(options: Pages.Options<T>): {
  extension: Scope.Extension;
  mount: NonNullable<HonoScope.Wiring["mount"]>;
} {
  const renders = new WeakMap<Request, () => Promise<Response>>();
  return {
    extension: extension({
      label: "stack.pages",
      hooks: {
        async session(event) {
          const incoming = event.resolve(request.optional);
          if (!incoming.present || renders.has(incoming.value)) return event.next();
          const raw = incoming.value;
          renders.set(raw, () =>
            event.handle.run({
              label: "stack.page",
              depends: { read: options.read },
              async run({ read }) {
                const values = await read.run();
                const content = createElement(ScopeProvider, {
                  scope: event.handle,
                  children: createElement(options.component),
                });
                return options.render(raw, values, content);
              },
            }),
          );
          try {
            return await event.next();
          } finally {
            renders.delete(raw);
          }
        },
      },
    }),
    mount(app) {
      app.get("*", async (c, next) => {
        if (c.req.path.startsWith("/assets/")) return next();
        const render = renders.get(c.req.raw);
        if (!render) return next();
        const response = await render();
        if (response.body === null) return response;
        const body = stream(c, pageBody, { input: response.body });
        return new Response(body.body, response);
      });
    },
  };
}

import { extension, operation, resource, type Operation, type Scope } from "@tinker/core";
import { request } from "../hono/index.ts";
import { nats, subscribe, type Nats } from "../nats/index.ts";
import { describeError } from "./observe.ts";
import { raise } from "./errors.ts";

export declare namespace LiveUpdates {
  type Wiring = {
    /** One literal subject per app, shared by its server processes. */
    subject: string;
    env: Nats.Wiring["env"];
    connection?: Nats.Wiring["connection"];
  };
}

/** The operation writes the root's published cells in the request's namespace
 * from committed storage.
 * Boot failures reject ready; failures after commit are logged and leave the
 * request's answer intact. Manual sessions and GET requests stay silent. */
export function publishAfterCommit(
  publish: Operation.Handle<unknown, void>,
): Scope.Extension<void> {
  return createPublisher(publish);
}

/** List the returned wiring as one nested row in the root's extensions.
 * The publisher and NATS extension belong to that root. Each empty signal
 * re-runs the operation at the root in the receiving namespace, including on
 * the sender. That read must be safe to repeat; it never sends a signal.
 * NATS owns subscription cleanup. */
export function liveUpdates(
  publish: Operation.Handle<unknown, void>,
  wiring: LiveUpdates.Wiring,
): readonly Scope.Extension[] {
  const refresh = resource({
    label: "stack.rootPublish",
    target: "namespace",
    depends: { publish },
    factory: ({ publish }) => publish,
  });
  const receive = operation({
    label: "stack.refresh",
    depends: { refresh },
    run: ({ refresh }, _ctx: Operation.Ctx<Nats.Message>) => refresh.run(),
  });
  const bus = nats([subscribe(wiring.subject, receive)], {
    env: wiring.env,
    connection: wiring.connection,
  });
  const changed = operation({
    label: "stack.changed",
    depends: { send: bus.publish },
    run: ({ send }) => send.run({ input: { subject: wiring.subject, payload: new Uint8Array() } }),
  });
  const publisher = createPublisher(publish, changed, () => {
    if (!/^[^\s.*>]+(?:\.[^\s.*>]+)*$/.test(wiring.subject)) {
      raise("BadLiveSubject", { subject: wiring.subject });
    }
  });
  return [publisher, bus.extension];
}

function createPublisher(
  publish: Operation.Handle<unknown, void>,
  changed?: Operation.Handle<unknown, void>,
  onStart?: () => void,
): Scope.Extension<void> {
  const republish = operation({
    label: "publish after commit",
    depends: { publish, ...(changed ? { changed } : {}) },
    run: async ({ publish, changed }, ctx) => {
      try {
        await publish.run();
        if (changed) await changed.run();
      } catch (error) {
        ctx.log.error("publish failed", describeError(error));
      }
    },
  });
  const root = resource({
    label: "stack.rootPublisher",
    target: "namespace",
    depends: { republish },
    factory: ({ republish }) => republish,
  });
  return extension({
    label: "stack.publish",
    hooks: {
      start: async (event) => {
        onStart?.();
        await event.next();
        event.scope.resolve(root);
        await event.scope.run(publish);
      },
      session: async (event) => {
        /** Resolve while the session is live; the controller belongs to the root
         * and keeps this session's namespace after the session closes. */
        const republish = event.handle.resolve(root);
        const ended = await event.next();
        const found = event.handle.resolve(request.optional);
        if (
          ended.status === "success" &&
          !ended.teardownErrors?.length &&
          found.present &&
          found.value.method !== "GET"
        ) {
          await republish.run();
        }
        return ended;
      },
    },
  });
}

import type { Server } from "node:http";
import { isIP } from "node:net";
import { serve } from "@hono/node-server";
import { extension, type Scope } from "@tinker/core";
import type { HonoScope } from "../hono/index.ts";
import { raise } from "./errors.ts";
import { mountClient } from "./client.ts";

export declare namespace Server {
  export type Env = { PORT?: string; HOST?: string };
  export type Options = {
    env: Env;
    clientDir: string;
  };
}

/** List first, before the Hono extension passed in: validate before other starts,
 * listen after they finish. Close stops accepting requests before draining the scope;
 * the defer joins the listener's close after those requests finish.
 * Accepted async tag reads drain before the listener stops.
 * Env and app are borrowed; no scope is made here. */
export function server(
  web: Scope.Extension<Parameters<HonoScope.Serve>[0]>,
  options: Server.Options,
): Scope.Extension<void> {
  let owner: Scope.Handle | undefined;
  return extension({
    label: "stack.server",
    hooks: {
      start: async (event) => {
        if (owner) raise("PieceInUse", { label: event.label });
        const scope = event.scope;
        owner = scope;
        let close: (() => Promise<void>) | undefined;
        let stopping: Promise<void> | undefined;
        let stopped = false;
        let closingScope = false;
        const stop = (): Promise<void> | undefined => {
          stopped = true;
          if (close) stopping ??= close();
          return stopping;
        };
        const release = () => {
          if (owner === scope) owner = undefined;
        };
        const closeScope = scope.close.bind(scope);
        /** The close hook has no scope. Bind here so a rejected or old root
         * cannot close the live owner's listener (as in the NATS piece). */
        scope.close = async (options) => {
          closingScope = true;
          try {
            /** The defer joins this promise after requests drain and reports listener errors. */
            stop()?.then(
              () => undefined,
              () => undefined,
            );
            return await closeScope(options);
          } finally {
            release();
          }
        };
        event.defer(async () => {
          try {
            await stop();
          } finally {
            /** Failed boot closes through core without calling the scope handle. */
            if (!closingScope) release();
          }
        });
        const settings = readSettings(options.env);
        await event.next();
        const app = scope.resolve(web);
        mountClient(app, options.clientDir);
        close = await listen(app, settings);
        if (stopped) await stop();
        else event.log.info("listening", settings);
      },
    },
  });
}

export function readSettings(env: Server.Env): { host: string; port: number } {
  const keys: string[] = [];
  const port = /^\d+$/.test(env.PORT ?? "") ? Number(env.PORT) : Number.NaN;
  if (!(port >= 1 && port <= 65535)) keys.push("PORT");
  const host = env.HOST ?? "";
  if (!isHost(host)) keys.push("HOST");
  if (keys.length > 0) raise("BadListenSettings", { keys });
  return { host, port };
}

function isHost(host: string): boolean {
  if (isIP(host) !== 0) return true;
  return (
    host.length <= 253 &&
    host.split(".").every((label) => /^[a-z\d](?:[a-z\d-]{0,61}[a-z\d])?$/i.test(label))
  );
}

function listen(
  app: Parameters<HonoScope.Serve>[0],
  settings: { host: string; port: number },
): Promise<() => Promise<void>> {
  return new Promise((resolve, reject) => {
    let closing = false;
    /** No custom createServer: the adapter always opens HTTP/1, though its type includes HTTP/2. */
    const listener = serve({ fetch: app.fetch, hostname: settings.host, port: settings.port }, () =>
      resolve(
        () =>
          new Promise<void>((done, fail) => {
            closing = true;
            listener.close((error) => (error ? fail(error) : done()));
          }),
      ),
    ) as Server;
    /** Streams can finish after close began; reap their now-idle keep-alive sockets too. */
    listener.on("request", (_request, response) => {
      response.once("finish", () => {
        if (closing) listener.closeIdleConnections();
      });
    });
    listener.once("error", reject);
  });
}

import type { PGlite } from "@electric-sql/pglite";
import { createScope, resource } from "@tinker/core";
import { migrate, type Migrate } from "./migrate.ts";

export declare namespace TestDatabase {
  export type Handle = {
    clone(): Promise<PGlite>;
    close(): Promise<void>;
  };
}

/** Builds one template through the boot migrate step. Ownership transfers to the
 * caller: close the template after the file/run and each clone after its test. */
export async function createTestDatabase(options: Migrate.Options): Promise<TestDatabase.Handle> {
  const { PGlite } = await import("@electric-sql/pglite");
  const { drizzle } = await import("drizzle-orm/pglite");
  const client = new PGlite();
  const database = resource({
    label: "test.db",
    factory: () => Promise.resolve(drizzle({ client })),
  });
  const scope = createScope({ extensions: [migrate(database, options)] });
  try {
    await scope.ready;
    return {
      /** PGlite's clone returns a PGlite; its declaration loses the class type. */
      clone: async () => (await client.clone()) as PGlite,
      close: () => client.close(),
    };
  } catch (error) {
    await client.close();
    throw error;
  } finally {
    await scope.close();
  }
}

import {
  data,
  extension,
  LEVELS,
  operation,
  resource,
  tag,
  type Clock,
  type Observe,
  type Operation,
  type Scope,
  type Tag,
} from "@tinker/core";
import { raise } from "./errors.ts";
import { jsonLines } from "./observe.ts";
import { encodeBatch, encodeLog, encodeSpan } from "./otlp.ts";

export declare namespace TraceSink {
  type Env = { OTEL_EXPORTER_OTLP_ENDPOINT?: string; OTEL_SERVICE_NAME?: string };
  type Wiring = {
    env: Env;
    /** Local JSON lines, without a trailing newline. Never sent back to OTLP. */
    write: (line: string) => void;
  };
  type Extension = Scope.Extension<Observe.Config> & {
    readonly config: Tag.Handle<Wiring>;
  };
}

/** Reuse this definition in telemetry roots with their own config tags.
 * Resolve it after ready and lend its observe config to app roots. Close the
 * apps before telemetry so graceful close exports their final records. */
export function traceSink(): TraceSink.Extension;
/** Legacy root-only wiring: make a fresh piece per observed root and pass
 * both its extension and observe config. Only graceful close flushes. */
export function traceSink(wiring: TraceSink.Wiring): {
  observe: Observe.Config;
  extension: Scope.Extension<void>;
};
export function traceSink(wiring?: TraceSink.Wiring) {
  return wiring === undefined ? createTraceExtension() : createRootTraceSink(wiring);
}

function createTraceExtension(): TraceSink.Extension {
  const config = tag<TraceSink.Wiring>({ label: "stack.trace.config" });
  /** Close must not resolve a failed queue and block the rest of cleanup. */
  const startedQueue = data<TraceQueue | undefined>({
    label: "stack.trace.startedQueue",
    initial: undefined,
  });
  const queue = resource({
    label: "stack.trace.queue",
    target: "scope",
    depends: { config: config.required },
    factory: ({ config }, ctx) => {
      const owned = new TraceQueue(readSettings(config.env), ctx.clock, jsonLines(config.write));
      ctx.defer(() => owned.stop());
      return owned;
    },
  });
  const ingest = operation({
    label: "stack.trace.ingest",
    depends: { queue },
    run: ({ queue }, ctx: Operation.Ctx<Observe.Span | Observe.Log>) => queue.ingest(ctx.input),
  });
  const exportBatch = operation({
    label: "stack.trace.export",
    depends: { queue },
    run: ({ queue }) => queue.flush(),
  });
  const observe = resource({
    label: "stack.trace.observe",
    target: "scope",
    depends: { ingest },
    factory: ({ ingest }): Observe.Config => ({
      export: (span) => ingest.run({ input: span }),
      log: (entry) => ingest.run({ input: entry }),
    }),
  });
  return Object.assign(
    extension({
      label: "stack.trace",
      hooks: {
        start: async (event) => {
          const owned = event.resolve(queue);
          event.controller(startedQueue).set(owned);
          const exporter = event.controller(exportBatch);
          owned.start(() => exporter.run());
          await event.next();
          return event.resolve(observe);
        },
        close: async (event) => {
          const owned = event.resolve(startedQueue);
          owned?.beginClose(event.options.graceful === true);
          try {
            return await event.next();
          } finally {
            await owned?.finishClose();
          }
        },
      },
    }),
    { config },
  );
}

function createRootTraceSink(wiring: TraceSink.Wiring) {
  const local = jsonLines(wiring.write);
  let queue: TraceQueue | undefined;
  const observe: Observe.Config = {
    export: (span) => {
      writeLocal(() => local.export?.(span));
      queue?.add(span);
    },
    log: (entry) => {
      writeLocal(() => local.log?.(entry));
      queue?.add(entry);
    },
  };
  return {
    observe,
    extension: extension({
      label: "stack.trace",
      hooks: {
        start: async (event) => {
          const settings = readSettings(wiring.env);
          const owned = new TraceQueue(settings, event.clock, local);
          queue = owned;
          owned.start(() => owned.flush());
          event.defer(async () => {
            await owned.stop();
          });
          await event.next();
        },
        close: async (event) => {
          const owned = queue;
          owned?.beginClose(event.options.graceful === true);
          try {
            return await event.next();
          } finally {
            await owned?.finishClose();
            queue = undefined;
          }
        },
      },
    }),
  };
}

function readSettings(env: TraceSink.Env): { endpoint: string; service: string } {
  const keys: string[] = [];
  const url = URL.parse(env.OTEL_EXPORTER_OTLP_ENDPOINT ?? "");
  if (
    !url ||
    !["http:", "https:"].includes(url.protocol) ||
    [url.username, url.password, url.search, url.hash].some(Boolean)
  ) {
    keys.push("OTEL_EXPORTER_OTLP_ENDPOINT");
  }
  const service = (env.OTEL_SERVICE_NAME ?? "").trim();
  if (!service) keys.push("OTEL_SERVICE_NAME");
  if (keys.length) raise("BadTraceSettings", { keys });
  return { endpoint: url!.href.replace(/\/$/, ""), service };
}

/** A broken local writer must not stop export or turn a collector fault into
 * a scope fault. This boundary is also used outside core's sink isolation. */
function writeLocal(write: () => void): void {
  try {
    write();
  } catch {
    return;
  }
}

class TraceQueue {
  private settings: { endpoint: string; service: string };
  private clock: Clock.Handle;
  private local: Observe.Config;
  private records: (Observe.Span | Observe.Log)[] = [];
  private state: "open" | "graceful" | "stopped" = "open";
  private warned = false;
  private pending?: Promise<void>;
  private timer?: Promise<void>;
  private stopTimer = new AbortController();
  private stopDeadline = new AbortController();
  private requests = new AbortController();
  private deadline?: Promise<void>;

  constructor(
    settings: { endpoint: string; service: string },
    clock: Clock.Handle,
    local: Observe.Config,
  ) {
    this.settings = settings;
    this.clock = clock;
    this.local = local;
  }

  ingest(record: Observe.Span | Observe.Log): void {
    writeLocal(() => ("level" in record ? this.local.log?.(record) : this.local.export?.(record)));
    this.add(record);
  }

  add(record: Observe.Span | Observe.Log): void {
    if (this.state === "stopped") {
      this.warn("scope closed");
      return;
    }
    if (this.records.length >= 2048) {
      this.warn("queue full");
      return;
    }
    this.records.push(record);
  }

  start(flush: () => Promise<void>): void {
    this.timer = this.runTimer(flush);
  }

  private async runTimer(flush: () => Promise<void>): Promise<void> {
    while (!this.stopTimer.signal.aborted) {
      try {
        await this.clock.sleep(1000, this.stopTimer.signal);
      } catch {
        return;
      }
      if (this.stopTimer.signal.aborted) return;
      await flush();
    }
  }

  async stop(): Promise<void> {
    /** A failed start can run defers without running the close hook. */
    if (this.state === "open") this.beginClose(false);
    await this.timer;
  }

  beginClose(graceful: boolean): void {
    this.stopTimer.abort();
    if (!graceful) this.drop("scope closed");
    else if (this.state === "open") {
      this.state = "graceful";
      this.deadline = this.waitForDeadline();
    }
  }

  async finishClose(): Promise<void> {
    if (this.state === "graceful") await this.flush();
    this.state = "stopped";
    this.stopDeadline.abort();
    await this.deadline;
  }

  private async waitForDeadline(): Promise<void> {
    try {
      await this.clock.sleep(1000, this.stopDeadline.signal);
    } catch {
      return;
    }
    this.drop("collector unavailable");
  }

  private drop(reason: string): void {
    this.state = "stopped";
    if (this.records.length || this.pending) this.warn(reason);
    this.records = [];
    this.requests.abort();
  }

  async flush(): Promise<void> {
    await this.pending;
    if (this.state === "stopped") return;
    const records = this.records;
    this.records = [];
    const batch = { traces: [] as string[], logs: [] as string[] };
    let bytes = 0;
    for (const record of records) {
      try {
        const log = "level" in record;
        const encoded = log ? encodeLog(record) : encodeSpan(record);
        const size = Buffer.byteLength(encoded);
        if (bytes + size > 1_048_576) {
          this.warn("queue full");
          continue;
        }
        batch[log ? "logs" : "traces"].push(encoded);
        bytes += size;
      } catch {
        this.warn("record could not be encoded");
      }
    }
    if (bytes === 0) return;
    this.pending = this.send(batch);
    try {
      await this.pending;
    } finally {
      this.pending = undefined;
    }
  }

  private async send(records: { traces: string[]; logs: string[] }): Promise<void> {
    const results = await Promise.all([
      this.post("traces", records.traces),
      this.post("logs", records.logs),
    ]);
    if (results.every(Boolean)) this.warned = false;
    else this.warn("collector unavailable");
  }

  private async post(signal: "traces" | "logs", records: string[]): Promise<boolean> {
    if (records.length === 0) return true;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 1000);
    try {
      const response = await fetch(`${this.settings.endpoint}/v1/${signal}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: encodeBatch(this.settings.service, signal, records),
        signal: AbortSignal.any([controller.signal, this.requests.signal]),
        redirect: "error",
      });
      await response.body?.cancel();
      return response.ok;
    } catch {
      return false;
    } finally {
      clearTimeout(timeout);
    }
  }

  private warn(reason: string): void {
    if (this.warned) return;
    this.warned = true;
    writeLocal(() =>
      this.local.log?.({
        time: this.clock.currentTimeMillis(),
        level: LEVELS.warn,
        message: "OTLP records dropped",
        attributes: { reason },
        span: undefined,
      }),
    );
  }
}
